mapper.insert:

    select seq_ann_board_post.nextval
    from dual

INSERT INTO apt_ann_board_post (    /*kr.or.ddit.domain.member.resident.mapper.IResidentBoardMapper.insertBoardFree*/
    ann_no
    ,ttl
    ,cn
    ,wrtr_id
    ,top_fix_yn
    ,pblanc_bgng_dt
    ,pblanc_end_dt
    ,reg_dttm
    ,mdf_dttm
    ,inq_cnt
    ,del_yn
    ,atch_file_id
    ,board_no
) VALUES (
    #{annNo}
    ,#{ttl}
    ,#{cn}
    ,#{wrtrId}
    ,NVL(#{topFixYn}, 'N')
    ,#{pblancBgngDt}
    ,#{pblancEndDt}
    ,SYSDATE
    ,SYSDATE
    ,0
    ,'N'
    ,#{atchFileId}
    ,#{boardNo}
)
